<script setup lang="ts">
import {ref,watch} from 'vue'
import AnnualWagePanel from './AnnualWagePanel.vue'
import {usePayrollPage} from '../payrollPage'
import {usePayrollWorkbenchText} from '../payrollWorkbenchText'
import {usePayrollProgressText} from '../payrollProgressText'
import type {PayrollWorkbenchData,WorkbenchMissing,WorkbenchReason} from '../payrollWorkbenchTypes'
import PayrollPaymentSummary from './PayrollPaymentSummary.vue'
import PayrollChangeComparison from './PayrollChangeComparison.vue'
import PhaseStatus from './PhaseStatus.vue'
const annualEmployee=ref('')
const props=defineProps<{companyId:string;month:string;batchId?:string;version?:number}>(),{api,load,loading,failure,base,home,store,issue,format}=usePayrollPage(),w=usePayrollWorkbenchText(),g=usePayrollProgressText(),data=ref<PayrollWorkbenchData|null>(null)
function refresh(){data.value=null;if(!props.companyId||!/^\d{4}-\d{2}$/.test(props.month))return;const company=props.companyId,month=props.month,id=props.batchId,version=props.version;const params=new URLSearchParams({companyId:company,month});if(id)params.set('batchId',id);if(version!=null)params.set('expectedVersion',String(version));void load(()=>api().get<PayrollWorkbenchData>('/payroll-workbench?'+params),v=>{if(company!==props.companyId||month!==props.month||id!==props.batchId||version!==props.version)return;if(v.companyId!==company||v.month!==month||(id&&v.batchId!==id)||(version!=null&&v.batchVersion!==version)){failure.value=w('mismatch');return}data.value=v})}
function action(row:WorkbenchMissing){const e=row.employeeId;if(row.action==='profile'&&e)return {path:base.value+'/pay-profiles/'+(row.profileId||'new'),query:{companyId:props.companyId,employeeId:e}};if(row.action==='input'&&e&&data.value?.batchId&&!data.value.frozen)return {path:base.value+'/payroll-batches/'+data.value.batchId+'/inputs/'+e};if(row.action==='employee'&&e&&(home.value?.headOffice||home.value?.employeeManage))return {path:base.value+'/employees/'+e+'/edit'};if(row.action==='policy'&&home.value?.headOffice)return {path:base.value+'/statutory-policies'};return null}
function employeeName(id:string|null){if(!id)return '—';const d=data.value;return d?.changes?.pending.find(x=>x.employeeId===id)?.employeeName||d?.payments.lines.find(x=>x.employeeId===id)?.employeeName||d?.missing.find(x=>x.employeeId===id)?.employeeName||d?.approvals.find(x=>x.employeeId===id)?.employeeName||id}
function reasonAction(row:WorkbenchReason){if(row.action==='approval'&&row.sourceId&&row.storeId&&(home.value?.headOffice||(home.value?.employeeManage&&store.value===row.storeId)))return {path:'/stores/'+row.storeId+'/workforce/approvals/'+row.sourceId};if(row.action==='profile'&&row.sourceId&&row.employeeId)return {path:base.value+'/pay-profiles/'+row.sourceId,query:{companyId:props.companyId,employeeId:row.employeeId}};if(row.action==='input'&&row.employeeId&&data.value?.batchId&&!data.value.frozen)return {path:base.value+'/payroll-batches/'+data.value.batchId+'/inputs/'+row.employeeId};if(row.action==='policy'&&home.value?.headOffice)return {path:base.value+'/statutory-policies'};return null}
watch(()=>props.companyId,()=>annualEmployee.value='')
watch(()=>[props.companyId,props.month,props.batchId,props.version],refresh,{immediate:true})
</script>
<template><section class="wf-section wf-workbench"><header class="wf-toolbar"><h3>{{w('title')}}</h3><button :disabled="loading" @click="refresh">{{w('refresh')}}</button></header><PhaseStatus :failure="failure" :loading="loading"/><template v-if="data"><p class="wf-hint">{{data.month}} · {{w('version')}} {{data.batchVersion??'—'}} · {{w('asOf')}} {{format(data.asOf,'Asia/Singapore')}} · {{w('calculated')}} {{format(data.calculatedAt,'Asia/Singapore')}}</p><p>{{w('missing')}} {{data.missingEmployees}} · {{w('pending')}} {{data.pendingEmployees}} · {{w('shifts')}} {{data.pendingShifts}} · {{w('context')}} {{data.contextShifts}} · {{w('exempt')}} {{data.exemptEmployees}}</p><p v-if="data.frozen" class="wf-issue">{{w('frozen')}}</p><p v-if="data.status==='published'" class="wf-issue">{{w('unsupported')}}</p><p v-if="data.status==='confirmed'" class="wf-hint">{{w('beforePublish')}}</p><h4>{{w('missingTitle')}}</h4><ul v-if="data.missing.length"><li v-for="(row,i) in data.missing" :key="i">{{row.employeeName||'—'}} · {{issue(row.code)}} <RouterLink v-if="action(row)" :to="action(row)!">{{w('open')}}</RouterLink></li></ul><h4>{{w('approvalTitle')}}</h4><p class="wf-hint">{{w('contextHint')}}</p><ul v-if="data.approvals.length"><li v-for="row in data.approvals" :key="row.scheduleId">{{row.employeeName}} · {{row.workDate}} · {{w(row.state==='missing'?'missingState':'stale')}} <RouterLink v-if="home?.headOffice||(home?.employeeManage&&store===row.storeId)" :to="{path:'/stores/'+row.storeId+'/workforce/approvals/'+row.scheduleId}">{{w('open')}}</RouterLink></li></ul><h4>{{w('reasons')}}</h4><ul><li v-for="(row,i) in data.reasons" :key="i">{{employeeName(row.employeeId)}} · {{w(row.kind)}} <RouterLink v-if="reasonAction(row)" :to="reasonAction(row)!">{{w('open')}}</RouterLink> <span v-if="row.sourceId"> · {{row.sourceId}}</span> <span v-if="row.oldVersion||row.newVersion">{{row.oldVersion||'—'}} → {{row.newVersion||'—'}}</span></li></ul><template v-if="data.changes"><h4>{{w('changes')}}</h4><p>{{g('pending')}} ({{data.changes.pending.length}}) · {{g('recalculated')}} {{data.changes.recalculated}} · {{g('reused')}} {{data.changes.reused}}</p><p v-if="data.changes.sourceChanged&&!data.frozen" class="wf-issue">{{g('sourceChangedHint')}}</p><PayrollChangeComparison :comparison="data.changes.lastCalculation" :title="g('lastCalculation')"/><PayrollChangeComparison :comparison="data.changes.previousMonth" :title="g('previousMonth')"/></template><p v-else class="wf-hint">{{w('noCalculation')}}</p><p v-if="data.payments.available&&!data.frozen" class="wf-hint">{{w('previewPayments')}}</p><PayrollPaymentSummary :data="data.payments"/><label>{{w('context')}} · OW / AW<select v-model="annualEmployee"><option value="">—</option><option v-for="row in data.payments.lines" :key="row.employeeId" :value="row.employeeId">{{row.employeeName}}</option></select></label><AnnualWagePanel v-if="annualEmployee" :company-id="companyId" :employee-id="annualEmployee" :year="Number(month.slice(0,4))" :source-version="version"/><p class="wf-hint">{{w('readyHint')}}</p></template></section></template>
<style scoped>.wf-workbench{padding:12px;border:1px solid #dbe4ee;border-radius:8px;overflow-wrap:anywhere}</style>
